const MAX_LINE_BYTES: usize = 4 * 1024 * 1024; // 4 MiB/line
const MAX_ENTRIES: usize = 1_000_000;
let mut buf = Vec::new();
let mut limited = reader.take(MAX_SESSION_BYTES as u64);
loop {
    buf.clear();
    let n = read_until_capped(&mut limited, b'\n', &mut buf, MAX_LINE_BYTES)?;
