fn validate_path_segment(segment: &str) -> bool {
    !segment.is_empty()
        && segment.len() <= 256
        && !segment.contains('/')
        && segment == segment.trim()
}

pub fn resolve_path(&self, path: &str) -> Option<i64> {
    let mut current = Self::ROOT_ID;
    for segment in path.split('/') {
        if !validate_path_segment(segment) {
            return None; // unchanged behaviour, but validation is now explicit
        }
        let child_ids = self.children.get(&current)?;
        let found = child_ids
            .iter()
            .find(|&&id| self.nodes.get(&id).is_some_and(|n| n.label == segment));
        current = *found?;
    }
